import type { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import { PrintButton } from '@/components/print-button'
import { formatThaiDateTime } from '@/lib/bm/thai-date'
import { getVendorEvaluationWorkspace } from '@/lib/server/vendor-evaluation'
import { vendorFiscalYearLabel } from '@/lib/vendors/fiscal-year'

export async function generateMetadata({ params }: { params: Promise<{ id: string }> }): Promise<Metadata> {
  return { title: `Annual Vendor Evaluation Report ${(await params).id}` }
}

const labels: Record<string, string> = {
  complete_delivery: 'Complete Delivery',
  shelf_life_compliance: 'Shelf-life compliance',
  packaging_compliance: 'Packaging compliance',
  temperature_compliance: 'Temperature compliance',
  documentation_discrepancies: 'Documentation discrepancies',
  complaint_resolution: 'Complaint resolution',
}

export default async function VendorEvaluationReportPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  let workspace
  try { workspace = await getVendorEvaluationWorkspace(id) } catch (error) {
    if (error instanceof Error && 'status' in error && (error as { status?: number }).status === 404) notFound()
    throw error
  }
  const currentApprovals = workspace.approvals.filter((approval) => approval.revision === workspace.documentState.revision)
  return <main className="vendor-evaluation-report-page"><div className="toolbar print-hidden"><Link href={`/vendors/evaluations/${id}`} className="back-link">กลับ evaluation</Link><PrintButton /></div><section className="sheet"><header className="report-header"><div><p className="eyebrow">MOLECULAR-CBH QMS · STOCK1</p><h1>Annual Vendor Evaluation</h1><p>{workspace.vendor.code} · {workspace.vendor.name}</p></div><div className="report-code"><span>รอบปีงบประมาณ</span><strong>{vendorFiscalYearLabel(workspace.evaluation.fiscalYear)}</strong><small>Revision {workspace.documentState.revision} · {workspace.documentState.status}</small></div></header>
    <section className="notice"><strong>{workspace.evaluation.resultLabel ?? 'ยังไม่ได้กำหนดสูตรคะแนน — รออนุมัติ'}</strong><span>ผลลัพธ์ numeric จะคงเป็น null จนกว่าจะมี policy ที่อนุมัติสำหรับ P-13/P-14</span></section>
    <section className="section"><h2>Metrics snapshot</h2><div className="metric-grid">{Object.values(workspace.evaluation.metricsSnapshot.metrics).map((metric) => <div key={metric.key} className="metric-card"><p>{labels[metric.key] ?? metric.key}</p><strong>{metric.display === 'count' ? metric.numerator : metric.denominator == null ? '-' : `${metric.numerator}/${metric.denominator}`}</strong><small>{metric.applicablePopulation}{metric.provisional ? ' · provisional' : ''}</small></div>)}</div><p className="caption">Delivery Lead Time: {workspace.evaluation.metricsSnapshot.deliveryLeadTime.meanDays == null ? '-' : `${workspace.evaluation.metricsSnapshot.deliveryLeadTime.meanDays.toFixed(1)} วันเฉลี่ย / ${workspace.evaluation.metricsSnapshot.deliveryLeadTime.medianDays?.toFixed(1) ?? '-'} วันมัธยฐาน`} · {workspace.evaluation.metricsSnapshot.deliveryLeadTime.label}</p></section>
    <section className="section judgment"><h2>Judgment</h2><div><h3>สรุปการประเมิน</h3><p>{workspace.evaluation.judgment.summary || '-'}</p></div><div><h3>จุดแข็ง</h3><p>{workspace.evaluation.judgment.strengths || '-'}</p></div><div><h3>ความเสี่ยง / ประเด็นต้องติดตาม</h3><p>{workspace.evaluation.judgment.risks || '-'}</p></div><div><h3>แผนการติดตาม</h3><p>{workspace.evaluation.judgment.actions || '-'}</p></div></section>
    <section className="section"><h2>Significant events</h2>{workspace.evaluation.significantEventsSnapshot.length ? <table><thead><tr><th>วันที่</th><th>ระดับ</th><th>ประเภท</th><th>รายละเอียด</th></tr></thead><tbody>{workspace.evaluation.significantEventsSnapshot.map((event) => <tr key={event.id}><td>{event.eventDate}</td><td>{event.severity}</td><td>{event.eventType}</td><td>{event.description}</td></tr>)}</tbody></table> : <p className="empty">ไม่มี significant event ใน snapshot นี้</p>}</section>
    <section className="section"><h2>Signature blocks</h2><div className="signature-grid">{(['evaluator', 'reviewer', 'approver'] as const).map((role) => { const approval = currentApprovals.find((item) => item.approvalRole === role); return <div className="signature-box" key={role}><p>{role}</p>{approval?.signatureAttachmentId ? <img src={`/api/attachments/${approval.signatureAttachmentId}`} alt={`ลายเซ็น ${role}`} /> : <div className="signature-empty">รอลงนาม</div>}<strong>{approval?.signerName ?? '-'}</strong><small>{approval ? new Date(approval.approvedAt).toLocaleDateString('th-TH') : '-'}</small></div> })}</div></section>
    <footer className="report-footer"><span>พิมพ์เมื่อ {formatThaiDateTime(new Date())}</span><span>เอกสาร revision {workspace.documentState.revision} · ลายเซ็นผูกกับ revision</span></footer>
  </section><style>{`@page{size:A4 portrait;margin:12mm}body{background:#e9eef0}.vendor-evaluation-report-page{color:#173d50;font-family:"Noto Sans Thai",Arial,sans-serif}.toolbar{display:flex;justify-content:space-between;align-items:center;max-width:794px;margin:0 auto 12px}.back-link,#print-report{border:1px solid #b8c8cc;border-radius:7px;background:#fff;color:#173d50;padding:8px 12px;font-size:13px;font-weight:700;text-decoration:none}.sheet{width:794px;min-height:1123px;margin:0 auto;padding:28px 32px 36px;background:#fff;box-shadow:0 10px 40px rgba(20,64,72,.16);-webkit-print-color-adjust:exact;print-color-adjust:exact}.report-header{display:flex;justify-content:space-between;gap:24px;padding-bottom:16px;border-bottom:2px solid #173d50}.eyebrow{margin:0;color:#0b7f76;font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.report-header h1{margin:5px 0 2px;font-size:24px}.report-header p:not(.eyebrow){margin:0;color:#55727c;font-size:12px}.report-code{text-align:right}.report-code span,.report-code small{display:block;color:#789097;font-size:10px}.report-code strong{display:block;margin:4px 0;font-family:"IBM Plex Mono",monospace;font-size:16px}.notice{display:flex;flex-direction:column;gap:3px;margin:16px 0;padding:10px 12px;border:1px solid #eed4a6;border-radius:7px;background:#fff9ed;color:#8b5c0b;font-size:11px}.notice span{color:#99601b}.section{margin-top:18px}.section h2{margin:0 0 7px;font-size:15px}.metric-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.metric-card{padding:10px 12px;border:1px solid #d8e4e5;border-radius:7px;background:#fbfdfd}.metric-card p{margin:0;color:#55727c;font-size:10px;font-weight:700}.metric-card strong{display:block;margin-top:3px;font-family:"IBM Plex Mono",monospace;font-size:19px}.metric-card small,.caption{display:block;margin-top:3px;color:#789097;font-size:9px;line-height:1.4}.judgment>div{margin-top:8px;padding:8px 10px;border:1px solid #d8e4e5;border-radius:6px}.judgment h3{margin:0;color:#55727c;font-size:10px}.judgment p{margin:4px 0 0;white-space:pre-wrap;font-size:11px;line-height:1.45}.section table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:10px}.section th,.section td{border:1px solid #cfdde0;padding:6px 5px;vertical-align:top;text-align:left}.section th{background:#eef4f4;color:#45636b;font-size:9px}.section td{word-break:break-word}.empty{padding:9px;border:1px solid #d8e4e5;color:#789097;font-size:10px}.signature-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.signature-box{min-height:145px;padding:8px;border:1px solid #cfdde0;border-radius:6px;text-align:center}.signature-box p{margin:0;color:#55727c;font-size:10px;font-weight:700}.signature-box img{display:block;width:100%;height:75px;object-fit:contain;margin:7px auto}.signature-empty{height:75px;margin:7px 0;border-bottom:1px dashed #9fbfc0;padding-top:32px;color:#9aafb4;font-size:10px}.signature-box strong,.signature-box small{display:block;font-size:10px}.signature-box small{margin-top:3px;color:#789097}.report-footer{display:flex;justify-content:space-between;gap:14px;margin-top:22px;padding-top:10px;border-top:1px solid #cfdde0;color:#789097;font-size:8px;line-height:1.5}@media(max-width:820px){.sheet{width:auto;min-height:0;margin:0;padding:18px}.signature-grid{grid-template-columns:1fr}.metric-grid{grid-template-columns:1fr}.section{overflow-x:auto}.section table{min-width:620px}}@media print{body{background:#fff}.print-hidden{display:none!important}.sheet{width:auto;min-height:0;margin:0;padding:0;box-shadow:none}}`}</style></main>
}
